module TopModule (
    input  logic clk,
    input  logic areset,
    input  logic x,
    output logic z
);

    logic carry;

    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            carry <= 1'b0;
            z     <= 1'b0;
        end else begin
            carry <= carry | x;
            z     <= x ^ carry; // uses current (old) carry before update
        end
    end

endmodule

