module TopModule (
    input  logic clk,
    input  logic areset,
    input  logic x,
    output logic z
);

    logic state, next_state;

    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= 1'b0;
        end else begin
            state <= next_state;
        end
    end

    // Mealy-type logic for serial 2's complementer
    assign next_state = state | x;
    assign z = x ^ state;

endmodule

module tb_TopModule;
    logic clk;
    logic areset;
    logic x;
    logic z;

    TopModule dut (
        .clk(clk),
        .areset(areset),
        .x(x),
        .z(z)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        areset = 1;
        x = 0;
        #12;
        areset = 0;
        #10;

        // Test vector 1: 0, 1, 0, 0 (LSB first of 0010 = +2)
        // Expected z: 0, 1, 1, 1 (LSB first of 1110 = -2)
        @(posedge clk); x = 0;
        @(posedge clk); x = 1;
        @(posedge clk); x = 0;
        @(posedge clk); x = 0;

        // Wait a cycle to observe last output
        @(posedge clk); x = 0; // padding or next test

        $display("SELFTEST PASS");
        $finish;
    end

endmodule

module tb_TopModule;
    logic clk;
    logic areset;
    logic x;
    logic z;

    TopModule dut (
        .clk(clk),
        .areset(areset),
        .x(x),
        .z(z)
    );

    always #5 clk = ~clk;

    task apply_and_check(input bit [7:0] data, input int len, input bit [7:0] expected);
        int i;
        begin
            for (i = 0; i < len; i++) begin
                @(posedge clk);
                #1; // small delay after clock edge to sample z
                x = data[i];
            end
            // We need one more clock cycle for the last bit output
            @(posedge clk);
            #1;
        end
    endtask

    // Let's do cycle-by-cycle checking
    initial begin
        clk = 0;
        areset = 1;
        x = 0;
        #15;
        areset = 0;
        @(posedge clk);

        // Test 1: +2 (0010) -> LSB first: 0, 1, 0, 0. Expected: 0, 1, 1, 1 (-2)
        // Cycle 1: x=0 -> z should be 0
        x = 0; @(posedge clk); #1; if (z !== 0) $fatal(1, "Fail T1.0: z=%b", z);
        // Cycle 2: x=1 -> z should be 1
        x = 1; @(posedge clk); #1; if (z !== 1) $fatal(1, "Fail T1.1: z=%b", z);
        // Cycle 3: x=0 -> z should be 1
        x = 0; @(posedge clk); #1; if (z !== 1) $fatal(1, "Fail T1.2: z=%b", z);
        // Cycle 4: x=0 -> z should be 1
        x = 0; @(posedge clk); #1; if (z !== 1) $fatal(1, "Fail T1.3: z=%b", z);

        // Test 2: Reset during operation
        areset = 1;
        @(posedge clk);
        areset = 0;
        @(posedge clk);

        // Test 3: 0 (0000) -> LSB first: 0, 0, 0, 0. Expected: 0, 0, 0, 0
        x = 0; @(posedge clk); #1; if (z !== 0) $fatal(1, "Fail T3.0: z=%b", z);
        x = 0; @(posedge clk); #1; if (z !== 0) $fatal(1, "Fail T3.1: z=%b", z);
        x = 0; @(posedge clk); #1; if (z !== 0) $fatal(1, "Fail T3.2: z=%b", z);
        x = 0; @(posedge clk); #1; if (z !== 0) $fatal(1, "Fail T3.3: z=%b", z);

        // Test 4: -4 (1100) -> LSB first: 0, 0, 1, 1. Expected: 0, 0, 1, 0 (+4)
        x = 0; @(posedge clk); #1; if (z !== 0) $fatal(1, "Fail T4.0: z=%b", z);
        x = 0; @(posedge clk); #1; if (z !== 0) $fatal(1, "Fail T4.1: z=%b", z);
        x = 1; @(posedge clk); #1; if (z !== 1) $fatal(1, "Fail T4.2: z=%b", z);
        x = 1; @(posedge clk); #1; if (z !== 0) $fatal(1, "Fail T4.3: z=%b", z);

        $display("SELFTEST PASS");
        $finish;
    end

endmodule

module TopModule (
    input  logic clk,
    input  logic areset,
    input  logic x,
    output logic z
);

    logic carry, next_carry;

    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            carry <= 1'b0;
        end else begin
            carry <= next_carry;
        end
    end

    // Serial 2's complementer logic:
    // When carry = 0: z = x, next_carry = x
    // When carry = 1: z = ~x, next_carry = 1
    // Equivalently:
    assign next_carry = carry | x;
    assign z = x ^ carry; // Wait, if carry is old carry or new carry?

endmodule

